import { useState, useCallback } from 'react';

export const useCommandTerminal = (
  isProcessing: boolean,
  onExecute: (prompt: string) => void
) => {
  const [userPrompt, setUserPrompt] = useState('');
  const [cmdHistory, setCmdHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  const handleExecute = useCallback(() => {
    if (userPrompt.trim()) {
      onExecute(userPrompt);
      setCmdHistory(prev => [userPrompt, ...prev]);
      setHistoryIndex(-1);
      setUserPrompt('');
    }
  }, [userPrompt, onExecute]);

  const handleInputKeyDown = useCallback((e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (!isProcessing) handleExecute();
    }
    // Command History Navigation
    if (e.ctrlKey) {
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        const nextIndex = historyIndex + 1;
        if (nextIndex < cmdHistory.length) {
          setHistoryIndex(nextIndex);
          setUserPrompt(cmdHistory[nextIndex]);
        }
      }
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        const prevIndex = historyIndex - 1;
        if (prevIndex >= 0) {
          setHistoryIndex(prevIndex);
          setUserPrompt(cmdHistory[prevIndex]);
        } else if (prevIndex === -1) {
          setHistoryIndex(-1);
          setUserPrompt('');
        }
      }
    }
  }, [historyIndex, cmdHistory, isProcessing, handleExecute]);

  return {
    userPrompt,
    setUserPrompt,
    handleInputKeyDown,
    handleExecute
  };
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, VALIDATOR_PROMPT, META_INSPECTION_PROMPT } from "./prompts";

// Schemas
const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

const VALIDATOR_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    verification_status: { type: Type.STRING, enum: ["CONFIRMED", "CORRECTED"] },
    reasoning: { type: Type.STRING, description: "Why was it confirmed or corrected?" },
    final_output: { type: Type.STRING, description: "The final text to display" }
  },
  required: ["verification_status", "reasoning", "final_output"]
};

const GENERIC_STEP_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Internal reasoning before generation" },
    output: { type: Type.STRING, description: "The result of the step task" },
    meta_data: { type: Type.OBJECT, description: "Any additional structured data required" }
  },
  required: ["thought_process", "output"]
};

const INSPECTION_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "Direct answer to the operator's query about internal state" },
    internal_state: { type: Type.STRING, description: "Technical summary of current mode or logic vectors" }
  },
  required: ["response", "internal_state"]
};

const uuid = () => Math.random().toString(36).substring(2, 9);

export class MultiAgentService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Cleans raw model output (which might include markdown code blocks) and parses it.
   */
  private cleanAndParseJSON(text: string): any {
    try {
      // Remove markdown code blocks if present (e.g. ```json ... ```)
      const cleanText = text.replace(/```json\n?|```\n?/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }

  private async callAgentJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    useTools: boolean = false,
    configOverrides: Partial<AgentConfig> = {}
  ): Promise<{ data: any; sources?: any[] }> {
    const MAX_RETRIES = 2;
    let attempt = 0;
    let lastError: any;

    while (attempt <= MAX_RETRIES) {
      try {
        // Configuration specifically for Gemini 3
        const config: any = {
          systemInstruction: systemPrompt,
          responseMimeType: "application/json",
          responseSchema: schema,
          temperature: configOverrides.temperature ?? 0.1, // Allow override or default strict
          // Enable Thinking for ALL agents to ensure high-quality reasoning
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192, // Reserve tokens for output (max - thinking)
        };

        if (configOverrides.topK) config.topK = configOverrides.topK;
        if (configOverrides.topP) config.topP = configOverrides.topP;

        // Add Search Tool only if requested
        if (useTools) {
          config.tools = [{ googleSearch: {} }];
        }

        const response = await this.ai.models.generateContent({
          model,
          contents: userPrompt,
          config,
        });

        const text = response.text;
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

        if (!text) throw new Error("Empty response from AI");

        return {
          data: this.cleanAndParseJSON(text),
          sources: groundingChunks
        };

      } catch (error) {
        lastError = error;
        attempt++;
        if (attempt <= MAX_RETRIES) {
          console.warn(`Agent execution failed (Attempt ${attempt}/${MAX_RETRIES}). Retrying in ${attempt * 1000}ms...`, error);
          await new Promise(resolve => setTimeout(resolve, attempt * 1000)); // Exponential backoff
        }
      }
    }

    console.error("Agent Execution Failed after retries:", lastError);
    throw lastError;
  }

  /**
   * EXECUTES A CUSTOM LINEAR OR COMPLEX WORKFLOW
   */
  public async runCustomChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-pro-preview'; // Upgrade to Pro for complex chains

    if (!config.workflow || config.workflow.length === 0) {
        throw new Error("Workflow mode activated but no steps defined.");
    }

    // Prepare History
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION HISTORY:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    let runningHistory = `${contextBlock}INITIAL USER REQUEST: "${userPrompt}"\n\n=== WORKFLOW START ===\n`;
    let lastOutput = "";

    // Iterate through steps
    for (const step of config.workflow) {
        const agentConfig = config.agents.find(a => a.name === step.agentName);
        if (!agentConfig) {
            onLog(this.createLog('system', 'SYSTEM', `ERROR: Agent '${step.agentName}' not found in configuration. Skipping step.`, false));
            continue;
        }

        onLog(this.createLog(agentConfig.role, agentConfig.name, `Initializing Step: ${step.name}...`, true));

        // Construct dynamic prompt for this step
        const stepPrompt = `
          CURRENT WORKFLOW STATE:
          ${runningHistory}

          YOUR ASSIGNMENT (${step.name}):
          ${step.instruction}

          INSTRUCTIONS:
          1. Review the history to understand the context.
          2. Execute your specific assignment based on the latest data.
          3. Output JSON with 'thought_process' and 'output'.
        `;

        const response = await this.callAgentJSON(
            modelName,
            generateSystemInstruction(agentConfig, config),
            stepPrompt,
            GENERIC_STEP_SCHEMA,
            true, // Enable tools by default for workflow steps
            { ...agentConfig, temperature: step.temperature ?? agentConfig.temperature }
        );

        lastOutput = response.data.output;
        runningHistory += `\n[STEP: ${step.name} | AGENT: ${agentConfig.name}]:\n${lastOutput}\n`;

        onLog(this.createLog(
            agentConfig.role,
            agentConfig.name,
            lastOutput,
            false,
            response.data,
            response.sources
        ));
    }

    return lastOutput;
  }

  /**
   * STANDARD ANALYST/SKEPTIC/JUDGE DEBATE PROTOCOL
   */
  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    const modelName = 'gemini-3-pro-preview'; // Upgrade to Pro for deep reasoning
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;
    // Optional Validator
    const validator = config.agents.find(a => a.role === 'validator');

    // Construct History Context
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION HISTORY:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    let history = `${contextBlock}CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan & logic vectors...", true));

    // Analyst gets Search Tools
    const analystRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(history),
      ANALYST_SCHEMA,
      true, // Enable Search
      analyst // Pass config overrides
    );

    currentDraft = analystRes.data.factual_answer;
    history += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog(
      'analyst', 
      analyst.name, 
      analystRes.data.factual_answer, 
      false, 
      analystRes.data,
      analystRes.sources
    ));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i;
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      const skepticRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(history, currentDraft),
        SKEPTIC_SCHEMA,
        true, // Enable Search for verification
        skeptic // Pass config overrides
      );

      history += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;

      const skepticLogContent = skepticRes.data.has_flaws 
        ? `OBJECTION: ${skepticRes.data.analysis}`
        : `AGREEMENT: ${skepticRes.data.analysis}`;

      onLog(this.createLog(
        'skeptic', 
        skeptic.name, 
        skepticLogContent, 
        false, 
        skepticRes.data,
        skepticRes.sources
      ));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }

      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(analyst, config),
        `CRITIQUE RECEIVED: ${skepticRes.data.analysis}\nSUGGESTED CORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        true, // Enable Search for rebuttal
        analyst
      );

      currentDraft = rebuttalRes.data.factual_answer;
      history += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog(
        'analyst', 
        analyst.name, 
        currentDraft, 
        false, 
        rebuttalRes.data,
        rebuttalRes.sources
      ));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    const judgeRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(history, consensus, roundsExecuted),
      JUDGE_SCHEMA,
      false, // Judge does not need search tools, uses context + thinking
      judge
    );

    let finalVerdict = judgeRes.data.final_verdict;

    onLog(this.createLog(
      'judge', 
      judge.name, 
      finalVerdict, 
      false, 
      judgeRes.data
    ));

    // --- OPTIONAL VALIDATOR ---
    if (validator) {
      onLog(this.createLog('validator', validator.name, "Running external fact-check on verdict...", true));

      const validatorRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(validator, config),
        VALIDATOR_PROMPT(finalVerdict),
        VALIDATOR_SCHEMA,
        true, // VALIDATOR NEEDS SEARCH
        validator
      );

      finalVerdict = validatorRes.data.final_output;

      const statusPrefix = validatorRes.data.verification_status === 'CONFIRMED' ? '✅' : '⚠';
      const logContent = `${statusPrefix} VERIFICATION COMPLETE: ${validatorRes.data.verification_status}\n\n${finalVerdict}`;

      onLog(this.createLog(
        'validator',
        validator.name,
        logContent,
        false,
        validatorRes.data,
        validatorRes.sources
      ));
    }

    return finalVerdict;
  }

  public async runAgentInspection(
    targetAgent: AgentConfig,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-pro-preview'; // Upgrade to Pro

    // Construct History
    const historyBlock = chatHistory.length > 0 
      ? chatHistory.map(turn => `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`).join("\n") 
      : "NO PREVIOUS HISTORY";

    onLog(this.createLog(targetAgent.role, targetAgent.name, `INTERROGATION INTERRUPT RECEIVED: "${userQuery}"`, true));

    // Execute Inspection
    const response = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(targetAgent, config),
      META_INSPECTION_PROMPT(historyBlock, userQuery),
      INSPECTION_SCHEMA,
      false,
      targetAgent
    );

    const logContent = `DIAGNOSTIC OUTPUT:\n${response.data.response}\n\n[STATUS: ${response.data.internal_state}]`;

    onLog(this.createLog(
      targetAgent.role, 
      targetAgent.name, 
      logContent, 
      false, 
      { thought_process: "Direct operator query bypassed standard debate logic." }
    ));

    return response.data.response;
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { ReasoningLog } from './features/reasoning/components/ReasoningLog';
import { ConfigEditor } from './features/reasoning/components/ConfigEditor';
import { VeritasHeader } from './features/reasoning/components/VeritasHeader';
import { VeritasSidebar } from './features/reasoning/components/VeritasSidebar';
import { BootSequence } from './components/BootSequence';
import { DEFAULT_CONFIG, PRESETS } from './features/reasoning/constants';
import { SystemConfig, ProcessState } from './features/reasoning/types';
import { useReasoningEngine } from './features/reasoning/hooks/useReasoningEngine';
import { useSoundFX } from './features/reasoning/hooks/useSoundFX';
import { useCommandTerminal } from './features/reasoning/hooks/useCommandTerminal';
import { Tooltip } from './components/Tooltip';

const CONFIG_STORAGE_KEY = 'veritas_system_config';

const App: React.FC = () => {
  // --- STATE MANAGEMENT ---
  const [isBooting, setIsBooting] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [activePreset, setActivePreset] = useState<string>('DEFAULT');
  const [isEditingConfig, setIsEditingConfig] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // --- CONFIGURATION ---
  const [config, setConfig] = useState<SystemConfig>(() => {
    try {
      const saved = localStorage.getItem(CONFIG_STORAGE_KEY);
      return saved ? JSON.parse(saved) : DEFAULT_CONFIG;
    } catch (e) {
      return DEFAULT_CONFIG;
    }
  });

  // --- HOOKS ---
  const { playBlip, playClick, playActivate, playDataStream, playVerdict, playError, isMuted, toggleMute } = useSoundFX();
  const { logs, processState, activeAgentName, currentRound, chatHistory, startReasoning, clearMemory } = useReasoningEngine(config);

  const isProcessing = processState !== ProcessState.IDLE && processState !== ProcessState.COMPLETE && processState !== ProcessState.ERROR;

  const { userPrompt, setUserPrompt, handleInputKeyDown, handleExecute } = useCommandTerminal(
    isProcessing,
    (prompt) => {
      playActivate();
      startReasoning(prompt);
      setIsSidebarOpen(false);
    }
  );

  // --- EFFECTS ---
  // Audio Triggers based on State
  useEffect(() => {
    if (isBooting) return;
    if (processState === ProcessState.ANALYZING) playActivate();
    if (processState === ProcessState.AUDITING) playDataStream();
    if (processState === ProcessState.COMPLETE) playVerdict();
    if (processState === ProcessState.ERROR) playError();
  }, [processState, playActivate, playDataStream, playVerdict, playError, isBooting]);

  // Audio Trigger on new logs
  useEffect(() => {
    if (isBooting) return;
    if (logs.length > 0) playBlip();
  }, [logs.length, playBlip, isBooting]);

  // Auto-focus Input
  useEffect(() => {
    if (!isBooting && !isProcessing && typeof window !== 'undefined' && window.matchMedia('(min-width: 768px)').matches) {
        textareaRef.current?.focus();
    }
  }, [processState, isBooting, isProcessing]);

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.metaKey || e.ctrlKey) {
            if (e.key === 'k') { e.preventDefault(); handleReset(); }
            if (e.key === 'e') { e.preventDefault(); handleExport(); }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [clearMemory, playClick]);

  // --- HANDLERS ---
  const handleSaveConfig = (newConfig: SystemConfig) => {
    setConfig(newConfig);
    localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(newConfig));
    setIsEditingConfig(false);
    setActivePreset('CUSTOM');
    playVerdict();
  };

  const handlePresetChange = (key: string) => {
      playClick();
      setActivePreset(key);
      setConfig(PRESETS[key]);
  };

  const handleExport = () => {
    playClick();
    const dataStr = JSON.stringify(logs, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `veritas_transcript_${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleReset = () => {
    playClick();
    clearMemory();
  }

  const handleInterrogate = (agentName: string) => {
      playClick();
      setUserPrompt(`@${agentName}: `);
      if (textareaRef.current) textareaRef.current.focus();
      setIsSidebarOpen(false);
  };

  if (isBooting) {
    return <BootSequence onComplete={() => setIsBooting(false)} />;
  }

  return (
    <div className="h-screen w-screen bg-veritas-black text-white font-sans selection:bg-veritas-cyan selection:text-black flex flex-col overflow-hidden crt-flicker">

      <VeritasHeader 
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
        isProcessing={isProcessing}
        processState={processState}
        currentRound={currentRound}
        maxRounds={config.max_rounds}
        activePreset={activePreset}
        presets={PRESETS}
        isMuted={isMuted}
        toggleMute={toggleMute}
        onPresetChange={handlePresetChange}
        onExport={handleExport}
        onReset={handleReset}
        onConfigOpen={() => { playClick(); setIsEditingConfig(true); }}
        playVerdict={playVerdict}
      />

      <main className="flex-1 flex overflow-hidden relative">
        <div className="absolute inset-0 bg-grid-pattern opacity-10 pointer-events-none"></div>

        <VeritasSidebar 
          isOpen={isSidebarOpen}
          setIsOpen={setIsSidebarOpen}
          config={config}
          processState={processState}
          activeAgentName={activeAgentName}
          activePreset={activePreset}
          presets={PRESETS}
          onPresetChange={handlePresetChange}
          onInterrogate={handleInterrogate}
        />

        {/* CENTER DASHBOARD */}
        <section className="flex-1 flex flex-col min-w-0 bg-black/20 relative z-10">
          <div className="flex-1 relative border-b border-zinc-800 overflow-hidden flex flex-col">
             <ReasoningLog logs={logs} agents={config.agents} />
          </div>

          {/* INPUT AREA */}
          <div className="bg-black border-t border-zinc-800 p-4 flex flex-col md:flex-row gap-4 items-center shrink-0 shadow-[-10px_-10px_30px_rgba(0,0,0,0.5)] z-20">
             <div className="flex-1 relative w-full h-24 md:h-24 group">
               <textarea 
                 ref={textareaRef}
                 value={userPrompt}
                 onChange={(e) => setUserPrompt(e.target.value)}
                 onKeyDown={handleInputKeyDown}
                 placeholder={
                    isProcessing ? "PROCESSING STREAM..." : 
                    chatHistory.length > 0 ? "ENTER FOLLOW-UP QUERY OR NEW TOPIC..." : 
                    "INPUT QUERY FOR VERIFICATION... (CTRL+UP for History)"
                 }
                 disabled={isProcessing}
                 className="w-full h-full bg-zinc-900/50 border border-zinc-800 text-veritas-cyan font-mono text-sm p-3 focus:outline-none focus:border-veritas-cyan/50 resize-none placeholder:text-zinc-700 disabled:opacity-50 transition-colors"
               />
               <div className="absolute top-0 right-0 p-1 pointer-events-none">
                 <div className="w-2 h-2 border border-zinc-600 group-focus-within:border-veritas-cyan transition-colors"></div>
               </div>
             </div>

             <div className="flex flex-col gap-2 w-full md:w-auto">
                 <Tooltip content="Initiate Multi-Agent Reasoning Chain (Enter)" position="left">
                    <button
                        onClick={handleExecute}
                        disabled={isProcessing || !userPrompt.trim()}
                        className="w-full h-12 md:h-16 px-8 bg-veritas-cyan/10 border border-veritas-cyan text-veritas-cyan font-mono font-bold tracking-wider hover:bg-veritas-cyan hover:text-black transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                    >
                        {isProcessing ? 'PROCESSING' : 'EXECUTE'}
                    </button>
                 </Tooltip>

                 {chatHistory.length > 0 && !isProcessing && (
                   <Tooltip content="Clear Context Memory & Logs (Ctrl+K)" position="left">
                        <button
                                onClick={handleReset}
                                className="w-full text-[9px] text-zinc-500 hover:text-veritas-red border border-transparent hover:border-zinc-800 py-1 transition-colors uppercase tracking-widest"
                            >
                                CLEAR CONTEXT
                        </button>
                    </Tooltip>
                 )}
             </div>
          </div>
        </section>
      </main>

      {/* MODAL */}
      {isEditingConfig && (
        <ConfigEditor config={config} onSave={handleSaveConfig} onClose={() => setIsEditingConfig(false)} />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, VALIDATOR_PROMPT, META_INSPECTION_PROMPT } from "./prompts";

// Schemas
const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

const VALIDATOR_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    verification_status: { type: Type.STRING, enum: ["CONFIRMED", "CORRECTED"] },
    reasoning: { type: Type.STRING, description: "Why was it confirmed or corrected?" },
    final_output: { type: Type.STRING, description: "The final text to display" }
  },
  required: ["verification_status", "reasoning", "final_output"]
};

const GENERIC_STEP_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Internal reasoning before generation" },
    output: { type: Type.STRING, description: "The result of the step task" },
    meta_data: { type: Type.OBJECT, description: "Any additional structured data required" }
  },
  required: ["thought_process", "output"]
};

const INSPECTION_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "Direct answer to the operator's query about internal state" },
    internal_state: { type: Type.STRING, description: "Technical summary of current mode or logic vectors" }
  },
  required: ["response", "internal_state"]
};

const uuid = () => Math.random().toString(36).substring(2, 9);

export class MultiAgentService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Cleans raw model output (which might include markdown code blocks) and parses it.
   */
  private cleanAndParseJSON(text: string): any {
    try {
      // Remove markdown code blocks if present (e.g. ```json ... ```)
      const cleanText = text.replace(/```json\n?|```\n?/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }

  private async callAgentJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    useTools: boolean = false,
    configOverrides: Partial<AgentConfig> = {}
  ): Promise<{ data: any; sources?: any[] }> {
    const MAX_RETRIES = 2;
    let attempt = 0;
    let lastError: any;

    while (attempt <= MAX_RETRIES) {
      try {
        // Configuration specifically for Gemini 3
        const config: any = {
          systemInstruction: systemPrompt,
          responseMimeType: "application/json",
          responseSchema: schema,
          temperature: configOverrides.temperature ?? 0.1, // Allow override or default strict
          // Enable Thinking for ALL agents to ensure high-quality reasoning
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192, // Reserve tokens for output (max - thinking)
        };

        if (configOverrides.topK) config.topK = configOverrides.topK;
        if (configOverrides.topP) config.topP = configOverrides.topP;

        // Add Search Tool only if requested
        if (useTools) {
          config.tools = [{ googleSearch: {} }];
        }

        const response = await this.ai.models.generateContent({
          model,
          contents: userPrompt,
          config,
        });

        const text = response.text;
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

        if (!text) throw new Error("Empty response from AI");

        return {
          data: this.cleanAndParseJSON(text),
          sources: groundingChunks
        };

      } catch (error) {
        lastError = error;
        attempt++;
        if (attempt <= MAX_RETRIES) {
          console.warn(`Agent execution failed (Attempt ${attempt}/${MAX_RETRIES}). Retrying in ${attempt * 1000}ms...`, error);
          await new Promise(resolve => setTimeout(resolve, attempt * 1000)); // Exponential backoff
        }
      }
    }

    console.error("Agent Execution Failed after retries:", lastError);
    throw lastError;
  }

  /**
   * GENERATE SPEECH (TTS)
   */
  public async generateSpeech(text: string): Promise<string> {
    try {
        const response = await this.ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' }, // Kore has a nice neutral/robotic tone
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data returned");
        return base64Audio;
    } catch (e) {
        console.error("TTS Failed:", e);
        throw e;
    }
  }

  /**
   * EXECUTES A CUSTOM LINEAR OR COMPLEX WORKFLOW
   */
  public async runCustomChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-pro-preview'; // Upgrade to Pro for complex chains

    if (!config.workflow || config.workflow.length === 0) {
        throw new Error("Workflow mode activated but no steps defined.");
    }

    // Prepare History
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION HISTORY:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    let runningHistory = `${contextBlock}INITIAL USER REQUEST: "${userPrompt}"\n\n=== WORKFLOW START ===\n`;
    let lastOutput = "";

    // Iterate through steps
    for (const step of config.workflow) {
        const agentConfig = config.agents.find(a => a.name === step.agentName);
        if (!agentConfig) {
            onLog(this.createLog('system', 'SYSTEM', `ERROR: Agent '${step.agentName}' not found in configuration. Skipping step.`, false));
            continue;
        }

        onLog(this.createLog(agentConfig.role, agentConfig.name, `Initializing Step: ${step.name}...`, true));

        // Construct dynamic prompt for this step
        const stepPrompt = `
          CURRENT WORKFLOW STATE:
          ${runningHistory}

          YOUR ASSIGNMENT (${step.name}):
          ${step.instruction}

          INSTRUCTIONS:
          1. Review the history to understand the context.
          2. Execute your specific assignment based on the latest data.
          3. Output JSON with 'thought_process' and 'output'.
        `;

        const response = await this.callAgentJSON(
            modelName,
            generateSystemInstruction(agentConfig, config),
            stepPrompt,
            GENERIC_STEP_SCHEMA,
            true, // Enable tools by default for workflow steps
            { ...agentConfig, temperature: step.temperature ?? agentConfig.temperature }
        );

        lastOutput = response.data.output;
        runningHistory += `\n[STEP: ${step.name} | AGENT: ${agentConfig.name}]:\n${lastOutput}\n`;

        onLog(this.createLog(
            agentConfig.role,
            agentConfig.name,
            lastOutput,
            false,
            response.data,
            response.sources
        ));
    }

    return lastOutput;
  }

  /**
   * STANDARD ANALYST/SKEPTIC/JUDGE DEBATE PROTOCOL
   */
  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    const modelName = 'gemini-3-pro-preview'; // Upgrade to Pro for deep reasoning
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;
    // Optional Validator
    const validator = config.agents.find(a => a.role === 'validator');

    // Construct History Context
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION HISTORY:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    let history = `${contextBlock}CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan & logic vectors...", true));

    // Analyst gets Search Tools
    const analystRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(history),
      ANALYST_SCHEMA,
      true, // Enable Search
      analyst // Pass config overrides
    );

    currentDraft = analystRes.data.factual_answer;
    history += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog(
      'analyst', 
      analyst.name, 
      analystRes.data.factual_answer, 
      false, 
      analystRes.data,
      analystRes.sources
    ));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i;
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      const skepticRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(history, currentDraft),
        SKEPTIC_SCHEMA,
        true, // Enable Search for verification
        skeptic // Pass config overrides
      );

      history += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;

      const skepticLogContent = skepticRes.data.has_flaws 
        ? `OBJECTION: ${skepticRes.data.analysis}`
        : `AGREEMENT: ${skepticRes.data.analysis}`;

      onLog(this.createLog(
        'skeptic', 
        skeptic.name, 
        skepticLogContent, 
        false, 
        skepticRes.data,
        skepticRes.sources
      ));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }

      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(analyst, config),
        `CRITIQUE RECEIVED: ${skepticRes.data.analysis}\nSUGGESTED CORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        true, // Enable Search for rebuttal
        analyst
      );

      currentDraft = rebuttalRes.data.factual_answer;
      history += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog(
        'analyst', 
        analyst.name, 
        currentDraft, 
        false, 
        rebuttalRes.data,
        rebuttalRes.sources
      ));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    const judgeRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(history, consensus, roundsExecuted),
      JUDGE_SCHEMA,
      false, // Judge does not need search tools, uses context + thinking
      judge
    );

    let finalVerdict = judgeRes.data.final_verdict;

    onLog(this.createLog(
      'judge', 
      judge.name, 
      finalVerdict, 
      false, 
      judgeRes.data
    ));

    // --- OPTIONAL VALIDATOR ---
    if (validator) {
      onLog(this.createLog('validator', validator.name, "Running external fact-check on verdict...", true));

      const validatorRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(validator, config),
        VALIDATOR_PROMPT(finalVerdict),
        VALIDATOR_SCHEMA,
        true, // VALIDATOR NEEDS SEARCH
        validator
      );

      finalVerdict = validatorRes.data.final_output;

      const statusPrefix = validatorRes.data.verification_status === 'CONFIRMED' ? '✅' : '⚠';
      const logContent = `${statusPrefix} VERIFICATION COMPLETE: ${validatorRes.data.verification_status}\n\n${finalVerdict}`;

      onLog(this.createLog(
        'validator',
        validator.name,
        logContent,
        false,
        validatorRes.data,
        validatorRes.sources
      ));
    }

    return finalVerdict;
  }

  public async runAgentInspection(
    targetAgent: AgentConfig,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-pro-preview'; // Upgrade to Pro

    // Construct History
    const historyBlock = chatHistory.length > 0 
      ? chatHistory.map(turn => `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`).join("\n") 
      : "NO PREVIOUS HISTORY";

    onLog(this.createLog(targetAgent.role, targetAgent.name, `INTERROGATION INTERRUPT RECEIVED: "${userQuery}"`, true));

    // Execute Inspection
    const response = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(targetAgent, config),
      META_INSPECTION_PROMPT(historyBlock, userQuery),
      INSPECTION_SCHEMA,
      false,
      targetAgent
    );

    const logContent = `DIAGNOSTIC OUTPUT:\n${response.data.response}\n\n[STATUS: ${response.data.internal_state}]`;

    onLog(this.createLog(
      targetAgent.role, 
      targetAgent.name, 
      logContent, 
      false, 
      { thought_process: "Direct operator query bypassed standard debate logic." }
    ));

    return response.data.response;
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import { useState, useCallback, useRef } from 'react';
import { MultiAgentService } from '../services/geminiService';

export const useSpeech = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  const initAudio = () => {
    if (!audioContextRef.current) {
        const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
        audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
        audioContextRef.current.resume();
    }
  };

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext
  ): Promise<AudioBuffer> => {
    // Gemini 2.5 TTS returns raw PCM 16-bit mono 24kHz
    // We need to convert Int16 to Float32 for Web Audio API
    const dataInt16 = new Int16Array(data.buffer);
    const channelCount = 1;
    const sampleRate = 24000;
    const frameCount = dataInt16.length;
    const buffer = ctx.createBuffer(channelCount, frameCount, sampleRate);

    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  const speak = useCallback(async (text: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return;

    // Stop current if playing
    if (sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
    }

    setIsPlaying(true);
    initAudio();

    try {
        const service = new MultiAgentService(apiKey);
        const base64Audio = await service.generateSpeech(text);

        if (!audioContextRef.current) return;

        const rawBytes = decode(base64Audio);
        const audioBuffer = await decodeAudioData(rawBytes, audioContextRef.current);

        const source = audioContextRef.current.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsPlaying(false);

        sourceRef.current = source;
        source.start();

    } catch (e) {
        console.error("Speech Error:", e);
        setIsPlaying(false);
    }
  }, []);

  const stop = useCallback(() => {
    if (sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
    }
  }, []);

  return { speak, stop, isPlaying };
};

import React, { useEffect, useRef, useState } from 'react';
import { LogEntry, AgentConfig } from '../types';
import { TerminalText } from '../../../components/TerminalText';
import { useSpeech } from '../hooks/useSpeech';

interface ReasoningLogProps {
  logs: LogEntry[];
  agents: AgentConfig[];
}

const CodeBlock: React.FC<{ code: string }> = ({ code }) => {
  // Regex patterns for syntax highlighting
  const patterns = {
    keyword: /\b(const|let|var|function|return|if|else|for|while|import|export|from|class|interface|type|async|await)\b/g,
    string: /("[^"]*"|'[^']*'|`[^`]*`)/g,
    number: /\b(\d+)\b/g,
    comment: /(\/\/.*$|\/\*[\s\S]*?\*\/)/gm,
    boolean: /\b(true|false|null|undefined)\b/g,
    functionCall: /\b([a-zA-Z0-9_]+)(?=\()/g
  };

  const highlightCode = (input: string) => {
    let output = input
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");

    output = output
      .replace(patterns.string, '<span class="text-green-400">$1</span>')
      .replace(patterns.comment, '<span class="text-zinc-500 italic">$1</span>')
      .replace(patterns.keyword, '<span class="text-veritas-cyan font-bold">$1</span>')
      .replace(patterns.boolean, '<span class="text-veritas-red">$1</span>')
      .replace(patterns.number, '<span class="text-veritas-gold">$1</span>')
      .replace(patterns.functionCall, '<span class="text-blue-300">$1</span>');

    return output;
  };

  return (
      <div className="my-3 bg-zinc-950 border border-zinc-800 rounded p-3 overflow-x-auto relative group">
        <div className="absolute top-0 right-0 px-2 py-0.5 text-[9px] text-zinc-600 font-mono border-b border-l border-zinc-800 rounded-bl bg-zinc-900 opacity-50 group-hover:opacity-100 transition-opacity">
            CODE_FRAGMENT
        </div>
        <pre className="text-[11px] font-mono leading-relaxed whitespace-pre">
            <code className="text-zinc-300" dangerouslySetInnerHTML={{ __html: highlightCode(code) }} />
        </pre>
      </div>
  );
};

export const ReasoningLog: React.FC<ReasoningLogProps> = ({ logs, agents }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [shouldAutoScroll, setShouldAutoScroll] = useState(true);
  const { speak, stop, isPlaying } = useSpeech();

  // Handle auto-scrolling
  useEffect(() => {
    if (scrollRef.current && shouldAutoScroll) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs, shouldAutoScroll]);

  const handleScroll = () => {
    if (scrollRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;
      const isAtBottom = scrollHeight - scrollTop - clientHeight < 100;
      setShouldAutoScroll(isAtBottom);
    }
  };

  const getAgentColor = (role: string) => {
    const agent = agents.find(a => a.role === role);
    return agent ? agent.color : 'text-gray-500';
  };

  // Helper to render content with code blocks detection
  const renderContent = (content: string, isThinking: boolean) => {
    if (isThinking) return content;

    const parts = content.split(/(```[\s\S]*?```)/g);

    return parts.map((part, index) => {
      if (part.startsWith('```')) {
        const rawCode = part.replace(/^```[a-z]*\n?|```$/g, '');
        return <CodeBlock key={index} code={rawCode} />;
      }
      if (!part.trim()) return null;
      return (
        <TerminalText 
          key={index}
          text={part} 
          speed={2} 
          scramble={false}
          className="text-zinc-300 whitespace-pre-wrap leading-relaxed block max-w-4xl" 
        />
      );
    });
  };

  return (
    <div className="h-full flex flex-col font-mono text-xs overflow-hidden relative bg-black">
      {/* Grid Background */}
      <div className="absolute inset-0 bg-grid-pattern opacity-20 pointer-events-none"></div>

      <div 
        ref={scrollRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto p-6 pb-20 space-y-8 scrollbar-hide z-10"
      >
        {logs.map((log) => {
          // --- RENDER: SYSTEM SEPARATOR ---
          if (log.agentRole === 'system') {
            return (
              <div key={log.id} className="flex items-center justify-center py-6 opacity-40">
                <div className="h-px bg-zinc-700 flex-1"></div>
                <span className="px-4 text-[9px] text-zinc-500 tracking-[0.2em]">{log.content}</span>
                <div className="h-px bg-zinc-700 flex-1"></div>
              </div>
            );
          }

          // --- RENDER: USER INPUT ---
          if (log.agentRole === 'user') {
            return (
              <div key={log.id} className="flex flex-col items-end mb-8 mt-4">
                 <div className="flex items-center gap-2 mb-1">
                    <span className="text-[10px] text-zinc-500">
                      [{new Date(log.timestamp).toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit" })}]
                    </span>
                    <span className="text-white font-bold bg-zinc-800 px-2 py-0.5 rounded text-[10px]">USER_INPUT</span>
                 </div>
                 <div className="bg-zinc-900 border border-zinc-700 p-3 rounded-bl-xl rounded-tl-xl rounded-tr-xl max-w-2xl text-white/90 text-sm">
                    {log.content}
                 </div>
              </div>
            );
          }

          // --- RENDER: FINAL VERDICT ---
          if (log.agentRole === 'verdict') {
            return (
              <div key={log.id} className="my-8 relative group">
                {/* Glow Effect */}
                <div className="absolute -inset-1 bg-veritas-gold/20 blur-lg opacity-50 group-hover:opacity-75 transition-opacity"></div>

                <div className="relative bg-zinc-950 border-2 border-veritas-gold p-6 md:p-8">
                  <div className="absolute -top-3 left-6 bg-zinc-950 px-2 text-veritas-gold font-bold tracking-widest text-sm flex items-center gap-2">
                    <span>⚖</span> FINAL VERDICT
                  </div>

                  <TerminalText 
                    text={log.content} 
                    speed={5} 
                    scramble={false}
                    className="text-sm md:text-base text-white font-medium leading-relaxed font-sans whitespace-pre-wrap block" 
                  />

                  <div className="mt-4 pt-4 border-t border-dashed border-zinc-800 flex justify-between items-center text-[9px] text-zinc-500 uppercase tracking-widest">
                    <div className="flex gap-4">
                        <span>Authenticity Verified</span>
                        <span>Session ID: {log.id.split('-')[0]}</span>
                    </div>

                    {/* TTS BUTTON */}
                    <button 
