                    {/* VISUALIZATION: SOURCES */}
                    {log.sources && log.sources.length > 0 && (
                      <div className="mt-2 pt-2 border-t border-zinc-900/50">
                        <p className="text-[9px] text-zinc-600 mb-1">REFERENCE NODES:</p>
                        <div className="flex flex-wrap gap-2">
                          {log.sources.map((src, idx) => (
                            src.web && (
                              <a 
                                key={idx} 
                                href={src.web.uri} 
                                target="_blank" 
                                rel="noreferrer"
                                className="text-[10px] text-veritas-cyan/70 hover:text-veritas-cyan hover:underline truncate max-w-[200px]"
                              >
                                🔗 {src.web.title || "External Source"}
                              </a>
                            )
                          ))}
                        </div>
                      </div>
                    )}

                    {/* VISUALIZATION: FLAWS (Skeptic) */}
                    {log.agentRole === 'skeptic' && log.metadata?.has_flaws && log.metadata?.flaws?.length > 0 && (
                      <div className="mt-3 bg-red-950/20 border border-red-900/50 p-3 rounded-sm">
                        <p className="text-veritas-red text-[10px] font-bold mb-2 uppercase tracking-wider">⚠ Logic Failures Detected:</p>
                        <ul className="list-none space-y-1">
                          {log.metadata.flaws.map((flaw: string, idx: number) => (
                            <li key={idx} className="text-red-400/80 text-[10px] pl-2 border-l border-red-900/50">
                              {flaw}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}

                     {/* VISUALIZATION: THOUGHT PROCESS */}
                     {log.metadata?.thought_process && (
                      <details className="group mt-2">
                        <summary className="cursor-pointer text-[9px] text-zinc-600 hover:text-zinc-400 list-none flex items-center gap-1">
                          <span className="opacity-50">▶</span> VIEW INTERNAL REASONING TRACE
                        </summary>
                        <div className="mt-2 pl-2 border-l border-zinc-800 text-zinc-500 text-[10px] italic">
                          {log.metadata.thought_process}
                        </div>
                      </details>
                    )}

                  </div>
                )}
              </div>
            </div>
          );
        })}

        {logs.length === 0 && (
          <div className="h-full flex items-center justify-center flex-col text-zinc-600 gap-4">
            <div className="w-16 h-16 border border-zinc-800 rounded-full flex items-center justify-center animate-spin-slow">
              <div className="w-2 h-2 bg-veritas-cyan rounded-full"></div>
            </div>
            <p className="tracking-widest text-xs">SYSTEM READY // WAITING FOR INPUT</p>
          </div>
        )}
      </div>
    </div>
  );
};

import { Type, Schema } from "@google/genai";

export const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

export const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

export const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

export const VALIDATOR_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    verification_status: { type: Type.STRING, enum: ["CONFIRMED", "CORRECTED"] },
    reasoning: { type: Type.STRING, description: "Why was it confirmed or corrected?" },
    final_output: { type: Type.STRING, description: "The final text to display" }
  },
  required: ["verification_status", "reasoning", "final_output"]
};

export const GENERIC_STEP_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Internal reasoning before generation" },
    output: { type: Type.STRING, description: "The result of the step task" },
    meta_data: { type: Type.OBJECT, description: "Any additional structured data required" }
  },
  required: ["thought_process", "output"]
};

export const INSPECTION_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "Direct answer to the operator's query about internal state" },
    internal_state: { type: Type.STRING, description: "Technical summary of current mode or logic vectors" }
  },
  required: ["response", "internal_state"]
};

import { GoogleGenAI, Schema, Modality } from "@google/genai";
import { AgentConfig } from "../types";

/**
 * GeminiCore: The low-level communication layer.
 * Responsibilities: 
 * 1. Initialize API
 * 2. Handle Retry Logic & Error handling
 * 3. Handle JSON Parsing/Cleaning
 * 4. Handle Raw TTS generation
 */
export class GeminiCore {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Generates a JSON response from a model with robust error handling and retries.
   */
  public async generateJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    useTools: boolean = false,
    configOverrides: Partial<AgentConfig> = {}
  ): Promise<{ data: any; sources?: any[] }> {
    const MAX_RETRIES = 2;
    let attempt = 0;
    let lastError: any;

    while (attempt <= MAX_RETRIES) {
      try {
        const config: any = {
          systemInstruction: systemPrompt,
          responseMimeType: "application/json",
          responseSchema: schema,
          temperature: configOverrides.temperature ?? 0.1,
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
        };

        if (configOverrides.topK) config.topK = configOverrides.topK;
        if (configOverrides.topP) config.topP = configOverrides.topP;
        if (useTools) config.tools = [{ googleSearch: {} }];

        const response = await this.ai.models.generateContent({
          model,
          contents: userPrompt,
          config,
        });

        const text = response.text;
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

        if (!text) throw new Error("Empty response from AI");

        return {
          data: this.cleanAndParseJSON(text),
          sources: groundingChunks
        };

      } catch (error) {
        lastError = error;
        attempt++;
        if (attempt <= MAX_RETRIES) {
          console.warn(`GeminiCore: Execution failed (Attempt ${attempt}/${MAX_RETRIES}). Retrying...`, error);
          await new Promise(resolve => setTimeout(resolve, attempt * 1000));
        }
      }
    }

    console.error("GeminiCore: Fatal Error after retries:", lastError);
    throw lastError;
  }

  /**
   * Generates raw audio bytes for TTS.
   */
  public async generateSpeech(text: string): Promise<string> {
    try {
        const response = await this.ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data returned");
        return base64Audio;
    } catch (e) {
        console.error("GeminiCore: TTS Failed:", e);
        throw e;
    }
  }

  private cleanAndParseJSON(text: string): any {
    try {
      const cleanText = text.replace(/```json\n?|```\n?/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }
}

import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, VALIDATOR_PROMPT, META_INSPECTION_PROMPT } from "./prompts";
import { ANALYST_SCHEMA, SKEPTIC_SCHEMA, JUDGE_SCHEMA, VALIDATOR_SCHEMA, GENERIC_STEP_SCHEMA, INSPECTION_SCHEMA } from "./schemas";
import { GeminiCore } from "./geminiCore";

const uuid = () => Math.random().toString(36).substring(2, 9);
const REASONING_MODEL = 'gemini-3-pro-preview';

/**
 * MultiAgentService (Orchestrator)
 * Responsibilities:
 * 1. Managing the debate flow (Analyst -> Skeptic -> Judge)
 * 2. Managing Custom Workflows
 * 3. Constructing Prompts
 * 4. Structuring Logs
 */
export class MultiAgentService {
  private core: GeminiCore;

  constructor(apiKey: string) {
    this.core = new GeminiCore(apiKey);
  }

  // --- PUBLIC API ---

  public async generateSpeech(text: string): Promise<string> {
    return this.core.generateSpeech(text);
  }

  public async runCustomChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {

    if (!config.workflow || config.workflow.length === 0) {
        throw new Error("Workflow mode activated but no steps defined.");
    }

    const runningHistory = this.buildContextHistory(chatHistory) + `INITIAL USER REQUEST: "${userPrompt}"\n\n=== WORKFLOW START ===\n`;
    let currentContext = runningHistory;
    let lastOutput = "";

    for (const step of config.workflow) {
        const agentConfig = config.agents.find(a => a.name === step.agentName);
        if (!agentConfig) {
            onLog(this.createLog('system', 'SYSTEM', `ERROR: Agent '${step.agentName}' not found. Skipping.`, false));
            continue;
        }

        onLog(this.createLog(agentConfig.role, agentConfig.name, `Initializing Step: ${step.name}...`, true));

        const stepPrompt = `
          CURRENT WORKFLOW STATE:
          ${currentContext}

          YOUR ASSIGNMENT (${step.name}):
          ${step.instruction}

          INSTRUCTIONS:
          1. Review the history to understand the context.
          2. Execute your specific assignment.
          3. Output JSON with 'thought_process' and 'output'.
        `;

        const { data, sources } = await this.core.generateJSON(
            REASONING_MODEL,
            generateSystemInstruction(agentConfig, config),
            stepPrompt,
            GENERIC_STEP_SCHEMA,
            true,
            { ...agentConfig, temperature: step.temperature ?? agentConfig.temperature }
        );

        lastOutput = data.output;
        currentContext += `\n[STEP: ${step.name} | AGENT: ${agentConfig.name}]:\n${lastOutput}\n`;

        onLog(this.createLog(agentConfig.role, agentConfig.name, lastOutput, false, data, sources));
    }

    return lastOutput;
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;
    const validator = config.agents.find(a => a.role === 'validator');

    let history = this.buildContextHistory(chatHistory) + `CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan...", true));

    const analystRes = await this.core.generateJSON(
      REASONING_MODEL,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(history),
      ANALYST_SCHEMA,
      true,
      analyst
    );

    currentDraft = analystRes.data.factual_answer;
    history += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog('analyst', analyst.name, currentDraft, false, analystRes.data, analystRes.sources));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i;
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      const skepticRes = await this.core.generateJSON(
        REASONING_MODEL,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(history, currentDraft),
        SKEPTIC_SCHEMA,
        true,
        skeptic
      );

      history += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;
      const skepticLogContent = skepticRes.data.has_flaws ? `OBJECTION: ${skepticRes.data.analysis}` : `AGREEMENT: ${skepticRes.data.analysis}`;
      onLog(this.createLog('skeptic', skeptic.name, skepticLogContent, false, skepticRes.data, skepticRes.sources));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }
      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.core.generateJSON(
        REASONING_MODEL,
        generateSystemInstruction(analyst, config),
        `CRITIQUE: ${skepticRes.data.analysis}\nCORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        true,
        analyst
      );

      currentDraft = rebuttalRes.data.factual_answer;
      history += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog('analyst', analyst.name, currentDraft, false, rebuttalRes.data, rebuttalRes.sources));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    const judgeRes = await this.core.generateJSON(
      REASONING_MODEL,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(history, consensus, roundsExecuted),
      JUDGE_SCHEMA,
      false, // Judge relies on pure reasoning + context
      judge
    );

    let finalVerdict = judgeRes.data.final_verdict;
    onLog(this.createLog('judge', judge.name, finalVerdict, false, judgeRes.data));

    // --- VALIDATOR (Optional) ---
    if (validator) {
      onLog(this.createLog('validator', validator.name, "Running external fact-check...", true));
      const validatorRes = await this.core.generateJSON(
        REASONING_MODEL,
        generateSystemInstruction(validator, config),
        VALIDATOR_PROMPT(finalVerdict),
        VALIDATOR_SCHEMA,
        true,
        validator
      );
      finalVerdict = validatorRes.data.final_output;
      const statusPrefix = validatorRes.data.verification_status === 'CONFIRMED' ? '✅' : '⚠';
      onLog(this.createLog('validator', validator.name, `${statusPrefix} VERIFICATION COMPLETE: ${validatorRes.data.verification_status}\n\n${finalVerdict}`, false, validatorRes.data, validatorRes.sources));
    }

    return finalVerdict;
  }

  public async runAgentInspection(
    targetAgent: AgentConfig,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const historyBlock = this.buildContextHistory(chatHistory) || "NO PREVIOUS HISTORY";

    onLog(this.createLog(targetAgent.role, targetAgent.name, `INTERROGATION INTERRUPT: "${userQuery}"`, true));

    const response = await this.core.generateJSON(
      REASONING_MODEL,
      generateSystemInstruction(targetAgent, config),
      META_INSPECTION_PROMPT(historyBlock, userQuery),
      INSPECTION_SCHEMA,
      false,
      targetAgent
    );

    const logContent = `DIAGNOSTIC OUTPUT:\n${response.data.response}\n\n[STATUS: ${response.data.internal_state}]`;
    onLog(this.createLog(targetAgent.role, targetAgent.name, logContent, false, { thought_process: "Direct operator query bypassed standard logic." }));

    return response.data.response;
  }

  // --- HELPERS ---

  private buildContextHistory(chatHistory: ChatHistoryItem[]): string {
    if (chatHistory.length === 0) return "";
    return "PREVIOUS CONVERSATION HISTORY:\n" + chatHistory.map(turn => 
        `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
    ).join("\n") + "\n\n";
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import { useState, useCallback, useRef } from 'react';
import { GeminiCore } from '../services/geminiCore';

export const useSpeech = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  const initAudio = () => {
    if (!audioContextRef.current) {
        const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
        audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
        audioContextRef.current.resume();
    }
  };

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const channelCount = 1;
    const sampleRate = 24000;
    const frameCount = dataInt16.length;
    const buffer = ctx.createBuffer(channelCount, frameCount, sampleRate);

    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  const speak = useCallback(async (text: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return;

    if (sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
    }

    setIsPlaying(true);
    initAudio();

    try {
        const core = new GeminiCore(apiKey);
        const base64Audio = await core.generateSpeech(text);

        if (!audioContextRef.current) return;

        const rawBytes = decode(base64Audio);
        const audioBuffer = await decodeAudioData(rawBytes, audioContextRef.current);

        const source = audioContextRef.current.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsPlaying(false);

        sourceRef.current = source;
        source.start();

    } catch (e) {
        console.error("Speech Error:", e);
        setIsPlaying(false);
    }
  }, []);

  const stop = useCallback(() => {
    if (sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
    }
  }, []);

  return { speak, stop, isPlaying };
};

import React from 'react';

interface CodeBlockProps {
  code: string;
}

export const CodeBlock: React.FC<CodeBlockProps> = ({ code }) => {
  // Regex patterns for syntax highlighting
  const patterns = {
    keyword: /\b(const|let|var|function|return|if|else|for|while|import|export|from|class|interface|type|async|await)\b/g,
    string: /("[^"]*"|'[^']*'|`[^`]*`)/g,
    number: /\b(\d+)\b/g,
    comment: /(\/\/.*$|\/\*[\s\S]*?\*\/)/gm,
    boolean: /\b(true|false|null|undefined)\b/g,
    functionCall: /\b([a-zA-Z0-9_]+)(?=\()/g
  };

  const highlightCode = (input: string) => {
    let output = input
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");

    output = output
      .replace(patterns.string, '<span class="text-green-400">$1</span>')
      .replace(patterns.comment, '<span class="text-zinc-500 italic">$1</span>')
      .replace(patterns.keyword, '<span class="text-veritas-cyan font-bold">$1</span>')
      .replace(patterns.boolean, '<span class="text-veritas-red">$1</span>')
      .replace(patterns.number, '<span class="text-veritas-gold">$1</span>')
      .replace(patterns.functionCall, '<span class="text-blue-300">$1</span>');

    return output;
  };

  return (
      <div className="my-3 bg-zinc-950 border border-zinc-800 rounded p-3 overflow-x-auto relative group">
        <div className="absolute top-0 right-0 px-2 py-0.5 text-[9px] text-zinc-600 font-mono border-b border-l border-zinc-800 rounded-bl bg-zinc-900 opacity-50 group-hover:opacity-100 transition-opacity">
            CODE_FRAGMENT
        </div>
        <pre className="text-[11px] font-mono leading-relaxed whitespace-pre">
            <code className="text-zinc-300" dangerouslySetInnerHTML={{ __html: highlightCode(code) }} />
        </pre>
      </div>
  );
};

import React from 'react';
import { LogEntry, AgentConfig } from '../types';
import { TerminalText } from '../../../components/TerminalText';
import { CodeBlock } from './CodeBlock';

interface LogItemProps {
  log: LogEntry;
  agents: AgentConfig[];
  onSpeak: (text: string) => void;
  onStop: () => void;
  isPlaying: boolean;
}

export const LogItem: React.FC<LogItemProps> = ({ log, agents, onSpeak, onStop, isPlaying }) => {
  const getAgentColor = (role: string) => {
    const agent = agents.find(a => a.role === role);
    return agent ? agent.color : 'text-gray-500';
  };

  const renderContent = (content: string, isThinking: boolean) => {
    if (isThinking) return content;
    const parts = content.split(/(```[\s\S]*?```)/g);
    return parts.map((part, index) => {
      if (part.startsWith('```')) {
        const rawCode = part.replace(/^```[a-z]*\n?|```$/g, '');
        return <CodeBlock key={index} code={rawCode} />;
      }
      if (!part.trim()) return null;
      return (
        <TerminalText 
          key={index}
          text={part} 
          speed={2} 
          scramble={false}
          className="text-zinc-300 whitespace-pre-wrap leading-relaxed block max-w-4xl" 
        />
      );
    });
  };

  // --- RENDER: SYSTEM SEPARATOR ---
  if (log.agentRole === 'system') {
    return (
      <div className="flex items-center justify-center py-6 opacity-40">
        <div className="h-px bg-zinc-700 flex-1"></div>
        <span className="px-4 text-[9px] text-zinc-500 tracking-[0.2em]">{log.content}</span>
        <div className="h-px bg-zinc-700 flex-1"></div>
      </div>
    );
  }

  // --- RENDER: USER INPUT ---
  if (log.agentRole === 'user') {
    return (
      <div className="flex flex-col items-end mb-8 mt-4">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-[10px] text-zinc-500">
              [{new Date(log.timestamp).toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit" })}]
            </span>
            <span className="text-white font-bold bg-zinc-800 px-2 py-0.5 rounded text-[10px]">USER_INPUT</span>
          </div>
          <div className="bg-zinc-900 border border-zinc-700 p-3 rounded-bl-xl rounded-tl-xl rounded-tr-xl max-w-2xl text-white/90 text-sm">
            {log.content}
          </div>
      </div>
    );
  }

  // --- RENDER: FINAL VERDICT ---
  if (log.agentRole === 'verdict') {
    return (
      <div className="my-8 relative group">
        <div className="absolute -inset-1 bg-veritas-gold/20 blur-lg opacity-50 group-hover:opacity-75 transition-opacity"></div>
        <div className="relative bg-zinc-950 border-2 border-veritas-gold p-6 md:p-8">
          <div className="absolute -top-3 left-6 bg-zinc-950 px-2 text-veritas-gold font-bold tracking-widest text-sm flex items-center gap-2">
            <span>⚖</span> FINAL VERDICT
          </div>
          <TerminalText 
            text={log.content} 
            speed={5} 
            scramble={false}
            className="text-sm md:text-base text-white font-medium leading-relaxed font-sans whitespace-pre-wrap block" 
          />
          <div className="mt-4 pt-4 border-t border-dashed border-zinc-800 flex justify-between items-center text-[9px] text-zinc-500 uppercase tracking-widest">
            <div className="flex gap-4">
                <span>Authenticity Verified</span>
                <span>Session ID: {log.id.split('-')[0]}</span>
            </div>
            <button 
                onClick={() => isPlaying ? onStop() : onSpeak(log.content)}
                className={`flex items-center gap-2 px-3 py-1 border transition-all duration-300 ${isPlaying ? 'border-veritas-cyan text-veritas-cyan bg-veritas-cyan/10 animate-pulse' : 'border-zinc-700 text-zinc-400 hover:text-white hover:border-zinc-500'}`}
            >
                <span>{isPlaying ? '■' : '▶'}</span>
                <span>{isPlaying ? 'TRANSMITTING VOICE...' : 'PLAY AUDIO'}</span>
            </button>
          </div>
        </div>
      </div>
    );
  }

  // --- RENDER: AGENT THINKING/OUTPUT (Standard) ---
  const agentColor = getAgentColor(log.agentRole);
  const borderColor = agentColor.replace('text-', 'border-');
  const bgColor = agentColor.replace('text-', 'bg-');
  const isSearchCapable = log.agentRole === 'analyst' || log.agentRole === 'skeptic';

  return (
    <div className={`group relative transition-all duration-500 ${log.isThinking ? 'opacity-90' : 'opacity-100'}`}>

      {/* Timestamp & Agent Header */}
      <div className="flex items-center gap-3 mb-2 border-b border-zinc-900 pb-1 w-max pr-4">
          <span className="text-[10px] text-zinc-600 font-bold">
            [{new Date(log.timestamp).toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" })}]
          </span>
          <span className={`${agentColor} font-bold tracking-wider uppercase flex items-center gap-2`}>
            //{log.agentName}
            {!log.isThinking && log.sources && log.sources.length > 0 && (
              <span className="flex items-center gap-1.5 text-[9px] bg-veritas-cyan/5 px-2 py-0.5 rounded-sm border border-veritas-cyan/20 text-veritas-cyan/90 tracking-widest">
                <span className="text-[10px]">📡</span> NET_ACCESS
              </span>
            )}
            {log.isThinking && (
              <span className="ml-2 flex items-center gap-1.5 text-[9px] opacity-70 border border-current px-1.5 py-0.5 rounded">
                <span className="relative flex h-1.5 w-1.5">
                  <span className={`animate-ping absolute inline-flex h-full w-full rounded-full ${bgColor} opacity-75`}></span>
                  <span className={`relative inline-flex rounded-full h-1.5 w-1.5 ${bgColor}`}></span>
                </span>
                {isSearchCapable ? 'REASONING_WITH_TOOLS...' : 'SYNTHESIZING_TRUTH...'}
              </span>
            )}
          </span>
      </div>

      <div className={`pl-4 border-l ${borderColor} ml-1`}>
        {log.isThinking ? (
            <div className={`${agentColor} font-mono flex flex-col gap-1`}>
              <div className="flex items-center gap-2 opacity-80">
                <span className="text-[10px] opacity-50">&gt;&gt;</span> 
                {log.content}
              </div>
              <div className="text-[9px] opacity-50 animate-pulse">
                ACCESSING VECTOR SPACE... CALCULATING PROBABILITY... 
              </div>
            </div>
        ) : (
          <div className="space-y-3">
            {/* VISUALIZATION: CONFIDENCE BAR (Analyst Only) */}
            {log.agentRole === 'analyst' && log.metadata?.confidence !== undefined && (
              <div className="w-64 mb-2">
                <div className="flex justify-between text-[9px] text-zinc-500 mb-1 uppercase">
                  <span>Certainty Level</span>
                  <span>{log.metadata.confidence}%</span>
                </div>
                <div className="h-1 bg-zinc-900 w-full overflow-hidden">
                  <div 
                    className={`h-full transition-all duration-1000 ${log.metadata.confidence > 80 ? 'bg-veritas-cyan' : log.metadata.confidence > 50 ? 'bg-veritas-gold' : 'bg-veritas-red'}`}
                    style={{ width: `${log.metadata.confidence}%` }}
                  ></div>
                </div>
              </div>
            )}

            <div>
                {renderContent(log.content, !!log.isThinking)}
            </div>

            {/* SOURCES */}
            {log.sources && log.sources.length > 0 && (
              <div className="mt-2 pt-2 border-t border-zinc-900/50">
                <p className="text-[9px] text-zinc-600 mb-1">REFERENCE NODES:</p>
                <div className="flex flex-wrap gap-2">
                  {log.sources.map((src, idx) => (
                    src.web && (
                      <a 
                        key={idx} 
                        href={src.web.uri} 
                        target="_blank" 
                        rel="noreferrer"
                        className="text-[10px] text-veritas-cyan/70 hover:text-veritas-cyan hover:underline truncate max-w-[200px]"
                      >
                        🔗 {src.web.title || "External Source"}
                      </a>
                    )
                  ))}
                </div>
              </div>
            )}

            {/* FLAWS */}
            {log.agentRole === 'skeptic' && log.metadata?.has_flaws && log.metadata?.flaws?.length > 0 && (
              <div className="mt-3 bg-red-950/20 border border-red-900/50 p-3 rounded-sm">
                <p className="text-veritas-red text-[10px] font-bold mb-2 uppercase tracking-wider">⚠ Logic Failures Detected:</p>
                <ul className="list-none space-y-1">
                  {log.metadata.flaws.map((flaw: string, idx: number) => (
                    <li key={idx} className="text-red-400/80 text-[10px] pl-2 border-l border-red-900/50">
                      {flaw}
                    </li>
                  ))}
                </ul>
              </div>
            )}

              {/* VISUALIZATION: THOUGHT PROCESS */}
              {log.metadata?.thought_process && (
              <details className="group mt-2">
                <summary className="cursor-pointer text-[9px] text-zinc-600 hover:text-zinc-400 list-none flex items-center gap-1">
                  <span className="opacity-50">▶</span> VIEW INTERNAL REASONING TRACE
                </summary>
                <div className="mt-2 pl-2 border-l border-zinc-800 text-zinc-500 text-[10px] italic">
                  {log.metadata.thought_process}
                </div>
              </details>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { LogEntry, AgentConfig } from '../types';
import { useSpeech } from '../hooks/useSpeech';
import { LogItem } from './LogItem';

interface ReasoningLogProps {
  logs: LogEntry[];
  agents: AgentConfig[];
}

export const ReasoningLog: React.FC<ReasoningLogProps> = ({ logs, agents }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [shouldAutoScroll, setShouldAutoScroll] = useState(true);
  const { speak, stop, isPlaying } = useSpeech();

  // Handle auto-scrolling
  useEffect(() => {
    if (scrollRef.current && shouldAutoScroll) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs, shouldAutoScroll]);

  const handleScroll = () => {
    if (scrollRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;
      const isAtBottom = scrollHeight - scrollTop - clientHeight < 100;
      setShouldAutoScroll(isAtBottom);
    }
  };

  return (
    <div className="h-full flex flex-col font-mono text-xs overflow-hidden relative bg-black">
      {/* Grid Background */}
      <div className="absolute inset-0 bg-grid-pattern opacity-20 pointer-events-none"></div>

      <div 
        ref={scrollRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto p-6 pb-20 space-y-8 scrollbar-hide z-10"
      >
        {logs.map((log) => (
          <LogItem 
            key={log.id} 
            log={log} 
            agents={agents} 
            onSpeak={speak}
            onStop={stop}
            isPlaying={isPlaying}
          />
        ))}

        {logs.length === 0 && (
          <div className="h-full flex items-center justify-center flex-col text-zinc-600 gap-4">
            <div className="w-16 h-16 border border-zinc-800 rounded-full flex items-center justify-center animate-spin-slow">
              <div className="w-2 h-2 bg-veritas-cyan rounded-full"></div>
            </div>
            <p className="tracking-widest text-xs">SYSTEM READY // WAITING FOR INPUT</p>
          </div>
        )}
      </div>
    </div>
  );
};
